/*
 * test_features.c -- parity for the feature-assembly half of the C reference.
 *
 * Checks jev_build_state (20 features + 2x64 normalised curves) and
 * jev_resample (raw trace -> 64 samples) against c/test_vectors.json /
 * c/test_features.h, generated by scripts/18_export_c.py.
 *
 *   gcc -std=c99 -O2 -o test_features test_features.c jev_head.c -lm
 */
#include <math.h>
#include <stdio.h>

#include "jev_head.h"
#include "test_features.h"
#include "test_common.h"

int main(void) {
    int c, i, failures = 0;
    float worst_feats = 0.0f, worst_curves = 0.0f, worst_resample = 0.0f;

    for (c = 0; c < JEV_SV_N; ++c) {
        jev_state s;
        float ku = JEV_SV_KU[0][c];
        float tu = JEV_SV_TU[0][c];
        jev_build_state(JEV_SV_METRICS[c], JEV_SV_Y[c], JEV_SV_U[c],
                        JEV_SV_GAINS[c], JEV_SV_GZN[c], ku, tu, JEV_SV_PREV[c],
                        JEV_SV_PREV_COST[0][c], JEV_SV_COST[0][c],
                        JEV_SV_ITER[0][c], 10.0f, 1.0f, &s);
        for (i = 0; i < JEV_N_FEATS; ++i) {
            float d = finite_diff(s.feats[i], JEV_SV_FEATS[c][i]);
            if (d > worst_feats) worst_feats = d;
        }
        for (i = 0; i < JEV_N_CURVE; ++i) {
            float d0 = finite_diff(s.curves[0][i], JEV_SV_CURVES[c][i]);
            float d1 = finite_diff(s.curves[1][i], JEV_SV_CURVES[c][JEV_N_CURVE + i]);
            if (d0 > worst_curves) worst_curves = d0;
            if (d1 > worst_curves) worst_curves = d1;
        }
    }
    if (worst_feats > JEV_TOL_FEATS || worst_curves > JEV_TOL_FEATS) {
        failures++;
        printf("FAIL build_state: feats %.3e curves %.3e\n", worst_feats,
               worst_curves);
    }

    for (c = 0; c < JEV_RV_N; ++c) {
        float y_out[JEV_N_CURVE], u_out[JEV_N_CURVE];
        jev_resample(JEV_RV_Y[c], JEV_RV_U[c], JEV_RV_LEN[c], y_out, u_out);
        for (i = 0; i < JEV_N_CURVE; ++i) {
            float dy = finite_diff(y_out[i], JEV_RV_Y_OUT[c][i]);
            float du = finite_diff(u_out[i], JEV_RV_U_OUT[c][i]);
            if (dy > worst_resample) worst_resample = dy;
            if (du > worst_resample) worst_resample = du;
        }
    }
    if (worst_resample > 1e-6f) {
        failures++;
        printf("FAIL resample: %.3e\n", worst_resample);
    }

    printf("state_cases %d resample_cases %d\n", JEV_SV_N, JEV_RV_N);
    printf("max_abs_diff_feats     %.3e (tol %.1e)\n", worst_feats,
           (double)JEV_TOL_FEATS);
    printf("max_abs_diff_curves    %.3e (tol %.1e)\n", worst_curves,
           (double)JEV_TOL_FEATS);
    printf("max_abs_diff_resample  %.3e\n", worst_resample);
    printf("failures %d\n", failures);
    return failures == 0 ? 0 : 1;
}
